/* @lc app=leetcode id=1803 lang=kotlin */
class Solution { fun countPairs(nums: IntArray, low: Int, high: Int): Int = IntArray(1000005).let { trie -> IntArray(1000005).let { count -> IntArray(1) { 1 }.let { nodes -> nums.sumOf { n -> ({ limit: Int -> (14 downTo 0).fold(0 to 1) { (acc, node), i -> if (node == 0) acc to 0 else (((limit shr i) and 1) to ((n shr i) and 1)).let { (l, b) -> if (l == 1) (acc + count[trie[node * 2 + b]]) to trie[node * 2 + (1 - b)] else acc to trie[node * 2 + b] } }.first }).let { countLess -> (countLess(high + 1) - countLess(low)).also { (14 downTo 0).fold(1) { node, i -> ((n shr i) and 1).let { b -> (trie[node * 2 + b].takeIf { it != 0 } ?: (++nodes[0]).also { trie[node * 2 + b] = it }).also { count[it]++ } } } } } } } } }